def V(label,segments=None,polygon=None,points=None):
 d={'label':label}
 for k,v in [('segments',segments),('polygon',polygon),('points',points)]:
  if v:d[k]=v
 return d
def M(p,e,views,labels=None,planar=False):
 d={'points':{k:list(map(float,v)) for k,v in p.items()},'edges':e,'views':{'neutral':V('Данные задачи'),**views},'labelNames':labels if labels is not None else [k for k in p if not k.startswith('_')]}
 if planar:d['planar']=True
 return d
def S(title,q,text,why,view='neutral',kind='theorem'):return {'title':title,'prompt':q,'explanation':text,'justifications':[{'kind':kind,'text':why}],'view':view}
