def chain(ns):return [[ns[i],ns[(i+1)%len(ns)]] for i in range(len(ns))]
def prism(base,shift):
 p={k:list(v) for k,v in base.items()};ns=list(base);p.update({k+'1':(np.array(v)+shift).tolist() for k,v in base.items()});e=chain(ns)+chain([k+'1' for k in ns])+[[k,k+'1'] for k in ns];return p,e

def square(a=3,h=4,shift=None):return prism({'A':[0,0,0],'B':[0,a,0],'C':[a,a,0],'D':[a,0,0]},[0,0,h] if shift is None else shift)
def box(x=3,y=4,h=5):return prism({'A':[0,0,0],'B':[0,y,0],'C':[x,y,0],'D':[x,0,0]},[0,0,h])
def equilateral(a=3,h=4,shift=None):return prism({'A':[0,0,0],'B':[a,0,0],'C':[a/2,a*math.sqrt(3)/2,0]},[0,0,h] if shift is None else shift)
def rhombus(a=3,angle=60,h=4):
 t=math.radians(angle);return prism({'A':[0,0,0],'B':[a,0,0],'C':[a+a*math.cos(t),a*math.sin(t),0],'D':[a*math.cos(t),a*math.sin(t),0]},[0,0,h])
def regular(n,a,h,hidden=False):
 r=a/(2*math.sin(math.pi/n));base={('_p'+str(i) if hidden else chr(65+i)):[r*math.cos(2*math.pi*i/n),r*math.sin(2*math.pi*i/n),0] for i in range(n)};return prism(base,[0,0,h])
def lerp(a,b,t):return (np.array(a)*(1-t)+np.array(b)*t).tolist()
def tri_area(p,a,b,c):return np.linalg.norm(np.cross(np.array(p[b])-p[a],np.array(p[c])-p[a]))/2

