L(16,16,'Наклонное боковое ребро','Угол между боковым ребром наклонной призмы и плоскостью основания равен 30°, высота призмы — 10 см. Найдите боковое ребро.','Найди длину бокового ребра.',M(p,e,{'projection':V('AH — проекция AA₁, A₁H — высота',segments=[['A','H'],['A1','H']]),'triangle':V('Прямоугольный треугольник AA₁H',polygon=['A','A1','H'])},labels=['A','A1','H','B','C']),[
 S('Прямоугольный треугольник','Как опустить высоту из верхней вершины?','Пусть H — проекция A₁ на плоскость нижнего основания. Тогда A₁H=10, ∠AHA₁=90°, а ∠A₁AH=30° — угол ребра с плоскостью.','Определение высоты и угла между прямой и плоскостью.','projection'),S('Синус','Какая сторона лежит напротив 30°?','Высота A₁H противолежит углу 30°, а боковое ребро AA₁ — гипотенуза. Поэтому sin30°=10/AA₁.','Определение синуса в прямоугольном треугольнике.','triangle'),S('Ответ','Какова длина гипотенузы?','AA₁=10/(1/2)=20 см.','sin30°=1/2.','triangle')], 'Высота — катет, боковое ребро — гипотенуза.',accepted=['20'])
