L(16,35,'Призма с трапецией в основании','Основание прямой призмы ABCDA₁B₁C₁D₁ — равнобедренная трапеция: BC=11 см, AD=21 см, AB=CD=13 см. Площадь диагонального сечения равна 180 см². Найдите: 1) площадь боковой поверхности; 2) площадь сечения через AD и B₁C₁.','Реши оба пункта.',M(p,e,{'base':V('Высота BH трапеции',polygon=list('ABCD'),segments=[['B','H']]),'diagonal':V('Диагональное сечение ACC₁A₁',polygon=['A','C','C1','A1']),'section':V('Наклонное сечение AB₁C₁D',polygon=['A','B1','C1','D'],segments=[['H','B1']])},labels=['A','B','C','D','B1','C1','H']),[
 S('Высота трапеции','Как использовать равные боковые стороны?','AH=(21−11)/2=5 см. В прямоугольном ABH получаем BH=√(13²−5²)=12 см. Горизонтальная проекция диагонали AC равна (21+11)/2=16 см.','Высоты равнобедренной трапеции и теорема Пифагора.','base'),S('Высота призмы','Какова диагональ основания?','AC=√(16²+12²)=20 см. Диагональное сечение — прямоугольник AC·h=180, поэтому h=9 см.','Теорема Пифагора и площадь прямоугольника.','diagonal'),S('Пункт 1','Каков периметр основания?','P=11+21+13+13=58 см, Sбок=Ph=58·9=522 см².','Боковая поверхность прямой призмы.','diagonal'),S('Пункт 2','Какова высота трапеции AB₁C₁D?','Её основания AD=21 и B₁C₁=11. Отрезок HB₁ перпендикулярен AD, его длина √(BH²+BB₁²)=√(144+81)=15 см. Поэтому Sсеч=(21+11)·15/2=240 см². Ответ:1)522 см²;2)240 см².','Теорема о трёх перпендикулярах, Пифагор и площадь трапеции.','section')], 'Сначала найди высоту и диагональ трапеции, затем высоту призмы.')
p,e=regular(6,6,8)
L(16,36,'Две возможные высоты','Диагональ боковой грани правильной шестиугольной призмы равна 10 см, площадь боковой поверхности — 288 см². Найдите сторону основания и высоту.','Укажи все пары размеров.',M(p,e,{'face':V('Прямоугольник со сторонами a,h',polygon=['A','B','B1','A1'],segments=[['A','B1']]),'base':V('Шесть равных сторон',polygon=list('ABCDEF'))},labels=['A','B','C','D','E','F','A1','B1']),[
 S('Система','Какие два равенства даёт условие?','Пусть a>0 — сторона основания, h>0 — высота. Диагональ грани даёт a²+h²=100; площадь даёт 6ah=288, то есть ah=48.','Пифагор и площадь боковой поверхности.','face'),S('Сумма и разность','Как восстановить два числа?','(a+h)²=100+96=196, значит a+h=14. (a−h)²=100−96=4, поэтому a−h=2 или −2.','Формулы квадрата суммы и разности.','face'),S('Все ответы','Можно ли выбрать только одну пару?','Получаем (a,h)=(8,6) или (6,8), в сантиметрах. Обе пары дают диагональ 10 и площадь 288, поэтому исключать одну нельзя. Модель показывает a=6,h=8.','Проверка обеих положительных пар в исходных условиях.','base')], 'Условия симметричны относительно a и h; проверь обе перестановки.',caption='Модель показывает одну из двух допустимых пар: сторона основания 6, высота 8. Вторая пара 8 и 6 разобрана в шагах; одна картинка не устраняет второй ответ.')
p,e=prism({'A':[0,0,0],'B':[8,0,1],'C':[0,15,0]},[0,0,9]);p.update({k+'s':[p[k][0],p[k][1],4] for k in 'ABC'})
L(16,37,'Перпендикулярные боковые грани','В наклонной треугольной призме грани AA₁B₁B и AA₁C₁C перпендикулярны. AA₁=9 см; расстояния между AA₁ и BB₁, между AA₁ и CC₁ равны 8 см и 15 см. Найдите площадь боковой поверхности.','Найди боковую площадь.',M(p,e,{'section':V('Перпендикулярное сечение AsBsCs',polygon=['As','Bs','Cs']),'faces':V('Две грани образуют прямой двугранный угол',segments=[['As','Bs'],['As','Cs'],['A','A1']]),'hyp':V('Третья сторона сечения',segments=[['Bs','Cs']])},labels=['A','A1','As','Bs','Cs']),[
 S('Перпендикулярное сечение','Как отобразить расстояния между параллельными рёбрами?','Пересечём прямые, содержащие боковые рёбра, плоскостью, перпендикулярной их направлению. При необходимости продолжаем рёбра и боковые грани: попадание на конечные отрезки не требуется. В полученном сечении AsBs=8 и AsCs=15 — общие перпендикуляры соответствующих рёбер.','Расстояние между параллельными прямыми.','section'),S('Угол сечения','Почему треугольник прямоугольный?','Угол BsAsCs — линейный угол двугранного угла двух данных граней, поэтому равен 90°. Третья сторона равна √(8²+15²)=17 см.','Определение линейного угла и теорема Пифагора.','faces'),S('Площадь','Как использовать периметр сечения?','Pсеч=8+15+17=40 см. Для наклонной призмы Sбок=l·Pсеч=9·40=360 см², так как стороны такого сечения задают расстояния между прямыми боковых рёбер — высоты соответствующих параллелограммов к ребру l.','Площадь параллелограмма и сумма площадей граней.','hyp')], 'Перпендикулярное рёбрам сечение имеет катеты 8 и 15.',accepted=['360'])
p,e=prism({'A':[0,0,0],'B':[16,0,1.6],'C':[-7,7*math.sqrt(3),-.7]},[0,0,15]);p.update({k+'s':[p[k][0],p[k][1],4] for k in 'ABC'})
L(16,38,'Ребро по наклонным боковым граням','Двугранный угол при одном боковом ребре наклонной треугольной призмы равен 120°. Расстояния от этого ребра до двух других равны 16 см и 14 см. Площадь боковой поверхности 840 см². Найдите боковое ребро.','Найди длину бокового ребра.',M(p,e,{'section':V('Сечение перпендикулярно боковым рёбрам',polygon=['As','Bs','Cs']),'angle':V('Две стороны 16,14 и угол 120°',segments=[['Bs','As'],['As','Cs']]),'edge':V('Боковое ребро',segments=[['A','A1']])},labels=['A','A1','As','Bs','Cs']),[
 S('Треугольник сечения','Какие известные элементы он имеет?','Пересечём прямые боковых рёбер плоскостью, перпендикулярной их направлению, при необходимости продолжая рёбра и грани. В полученном треугольнике две стороны равны 16 и 14, а угол между ними — линейный угол данного двугранного угла, то есть 120°.','Расстояние между параллельными прямыми и линейный угол.','angle'),S('Третья сторона','Как применить теорему косинусов?','c²=16²+14²−2·16·14 cos120°=256+196+224=676. Значит c=26 см, периметр P=16+14+26=56 см.','Теорема косинусов; cos120°=−1/2.','section'),S('Искомое ребро','Как связаны площадь и периметр?','Sбок=lP, поэтому l=840/56=15 см.','Боковая поверхность наклонной призмы через перпендикулярное сечение.','edge')], 'Сначала примени теорему косинусов к перпендикулярному сечению.',accepted=['15'])
p,e=equilateral(8,6);p['D']=lerp(p['A1'],p['C1'],.5);p['E']=lerp(p['B1'],p['C1'],.5);p['H']=[2,0,0];p['K']=[2,2*math.sqrt(3),0]
L(16,39,'Сечение через середины верхних рёбер','Высота правильной треугольной призмы ABCA₁B₁C₁ равна 6 см. D,E — середины A₁C₁ и B₁C₁. Плоскость ABED образует с основанием угол 60°. Найдите площадь сечения ABED.','Найди площадь трапеции.',M(p,e,{'angle':V('DH наклонено к проекции KH под 60°',segments=[['D','H'],['H','K'],['D','K']]),'section':V('Сечение ABED',polygon=['A','B','E','D']),'base':V('Равностороннее основание',polygon=list('ABC'))},labels=['A','B','C','D','E','H','K']),[
 S('Проекция высоты сечения','Как далеко середины верхних рёбер от AB в проекции?','Пусть сторона основания a. Высота равностороннего ABC равна a√3/2; проекция D — середина AC, поэтому расстояние KH до AB равно a√3/4. DK=6.','Средняя линия и высота равностороннего треугольника.','angle'),S('Сторона основания','Что даёт угол 60°?','tan60°=DK/KH=6/(a√3/4). Следовательно a=8 см, DE=a/2=4 см.','Линейный угол двугранного угла и тангенс.','base'),S('Высота и площадь трапеции','Чему равна DH?','KH=2√3, поэтому DH=√((2√3)²+6²)=4√3. Тогда S=(AB+DE)·DH/2=(8+4)·4√3/2=24√3 см².','Пифагор и площадь трапеции.','section')], 'Высота сечения вместе с её проекцией образует прямоугольный треугольник.')
a=4*math.sqrt(2);p,e=square(a,6);p['O']=[a/2,a/2,0];p['M']=[a,0,3]
L(16,40,'Сечение параллельно диагонали призмы','Сторона основания правильной четырёхугольной призмы равна 4√2 см, высота 6 см. Через диагональ основания проведена плоскость, параллельная диагонали призмы. Найдите площадь сечения.','Найди площадь треугольного сечения.',M(p,e,{'parallel':V('OM параллелен BD₁',segments=[['O','M'],['B','D1']]),'section':V('Сечение ACM',polygon=['A','C','M']),'diagonal':V('Прямоугольный треугольник BDD₁',polygon=['B','D','D1'])},labels=['A','B','C','D','D1','O','M']),[
 S('Построение','Как провести нужное направление через центр?','Выберем диагональ основания AC и диагональ призмы BD₁. Они скрещиваются. Пусть O — центр основания. В треугольнике DBD₁ точка O — середина DB; прямая через O параллельно BD₁ пересекает DD₁ в середине M. Плоскость ACM — искомая.','Теорема о средней линии треугольника.','parallel'),S('Размеры','Чему равны AC и OM?','AC=BD=(4√2)√2=8 см. BD₁=√(8²+6²)=10 см. Поэтому OM=BD₁/2=5 см.','Диагональ квадрата, Пифагор и средняя линия.','diagonal'),S('Высота треугольника','Почему OM перпендикулярен AC?','AC перпендикулярен BD и вертикальному направлению DD₁, поэтому перпендикулярен плоскости BDD₁ и её прямой OM. Значит S_ACM=AC·OM/2=8·5/2=20 см². Симметрия квадрата даёт тот же ответ для остальных допустимых выборов.','Признак перпендикулярности прямой и плоскости.','section')], 'Через центр основания проведи прямую, параллельную пространственной диагонали.',accepted=['20'])
p,e=square(3,4)
L(16,41,'Сечение между диагоналями соседних граней','Высота правильной четырёхугольной призмы равна h. Угол между диагоналями соседних боковых граней, проведёнными из одной вершины, равен α. Найдите площадь сечения, проходящего через эти диагонали.','Выведи площадь через h,α.',M(p,e,{'section':V('Сечение BA₁D',polygon=['B','A1','D']),'face':V('Диагонали A₁B и A₁D равны L',segments=[['A1','B'],['A1','D']]),'base':V('BD — диагональ квадрата',segments=[['B','D'],['A','B'],['A','D']])}),[
 S('Общие длины','Как связать диагональ грани и сторону основания?','Пусть сторона основания a, длина диагонали боковой грани L. Тогда L²=a²+h², а BD=a√2. Искомое сечение — равнобедренный треугольник BA₁D с углом α между сторонами L.','Пифагор и строение сечения.','section'),S('Косинус угла','Что даёт теорема косинусов?','BD²=2L²(1−cosα), то есть 2a²=2L²(1−cosα). Вычитая a² из L², получаем h²=L²cosα. Поэтому L²=h²/cosα; для невырожденной призмы 0<α<90°.','Теорема косинусов.','base'),S('Площадь','Как использовать две стороны и угол?','S=L²sinα/2=h²sinα/(2cosα)=(h²/2)tanα.','Площадь треугольника по двум сторонам и углу.','face')], 'Обозначь обе диагонали граней одной буквой L.')
p,e=equilateral(3,4)
L(16,42,'Угол диагоналей треугольной призмы','Высота правильной треугольной призмы равна h. Угол между диагоналями двух боковых граней, проведёнными из одной вершины, равен α. Найдите площадь сечения, содержащего эти диагонали.','Выведи формулу площади.',M(p,e,{'section':V('Сечение BA₁C',polygon=['B','A1','C']),'face':V('Равные диагонали A₁B и A₁C',segments=[['A1','B'],['A1','C']]),'base':V('Сторона основания BC=a',segments=[['B','C']])}),[
 S('Стороны треугольника','Как связаны L,a,h?','Пусть L — диагональ боковой грани, a — сторона основания. Тогда L²=a²+h². В сечении BA₁C две стороны равны L, а третья равна a.','Пифагор в боковой грани.','face'),S('Устраняем a','Что даёт теорема косинусов?','a²=2L²(1−cosα). Значит h²=L²−a²=L²(2cosα−1), откуда L²=h²/(2cosα−1). Положительность h требует 0<α<60°.','Теорема косинусов и положительность квадрата длины.','base'),S('Площадь','Чему равно S?','S=L²sinα/2=h²sinα/[2(2cosα−1)]. Равносильная запись: h²sinα/[2(1−4sin²(α/2))].','Площадь по двум сторонам и углу; cosα=1−2sin²(α/2).','section')], 'В отличие от квадратного основания здесь основание сечения равно a, а не a√2.')
