L(17,2,'Диагональное сечение прямого параллелепипеда','Докажите, что плоскость диагонального сечения прямого параллелепипеда перпендикулярна плоскости его основания.','Докажи перпендикулярность плоскостей.',M(p,e,{'section':V('Диагональное сечение ACC₁A₁',polygon=['A','C','C1','A1']),'height':V('AA₁ перпендикулярно основанию',segments=[['A','A1']]),'base':V('Плоскость основания',polygon=list('ABCD'))}),[
 S('Определяем сечение','Какое боковое ребро оно содержит?','Диагональное сечение проходит через диагональ основания и боковые рёбра её концов. Например, плоскость ACC₁A₁ содержит AA₁.','Определение диагонального сечения.','section'),S('Перпендикуляр','Как расположено AA₁?','Параллелепипед прямой, поэтому его боковое ребро AA₁ перпендикулярно плоскости основания ABCD.','Определение прямой призмы.','height'),S('Вывод о плоскостях','Какой признак применим?','Плоскость, содержащая прямую, перпендикулярную другой плоскости, сама перпендикулярна этой плоскости. Значит (ACC₁A₁)⊥(ABCD). То же доказательство работает для второго диагонального сечения.','Признак перпендикулярности плоскостей.','base')], 'Найди в плоскости сечения боковое ребро.')
p,e=box(12,5,13*math.sqrt(3))
L(17,3,'Высота прямоугольного параллелепипеда','Стороны основания прямоугольного параллелепипеда равны 5 см и 12 см. Его диагональ образует с плоскостью основания угол 60°. Найдите высоту.','Найди высоту.',M(p,e,{'base':V('Диагональ прямоугольника AC',polygon=['A','B','C']),'triangle':V('Прямоугольный треугольник ACC₁',polygon=['A','C','C1'])}),[
 S('Проекция диагонали','Чему равна диагональ основания?','AC=√(5²+12²)=13 см. Это ортогональная проекция пространственной диагонали AC₁ на основание.','Пифагор и перпендикулярность CC₁ основанию.','base'),S('Угол с основанием','Какой угол равен 60°?','∠C₁AC=60°. В прямоугольном ACC₁ катет CC₁=h противолежит этому углу, а AC=13 прилежит. Поэтому tan60°=h/13.','Определение угла прямой с плоскостью.','triangle'),S('Ответ','Чему равна высота?','h=13tan60°=13√3 см.','tan60°=√3.','triangle')], 'Сначала найди диагональ основания.')
