L(17,5,'Углы прямых с боковыми гранями','В прямоугольном параллелепипеде ABCDA₁B₁C₁D₁ AB=5 см, AD=7 см, AA₁=12 см. Найдите угол: 1) между DC₁ и плоскостью BCC₁; 2) между B₁D и плоскостью ABB₁.','Реши оба пункта.',M(p,e,{'first':V('Проекция DC₁ на BCC₁ — CC₁',polygon=['D','C','C1']),'second':V('Проекция DB₁ на ABB₁ — AB₁',polygon=['D','A','B1']),'face':V('AB₁ — диагональ прямоугольника 5×12',polygon=['A','B','B1'])}),[
 S('Пункт 1: проекция','Куда проектируется D?','DC перпендикулярен грани BCC₁, поэтому D проектируется в C, а DC₁ — в CC₁. Искомый угол ∠DC₁C, tan∠DC₁C=DC/CC₁=5/12. Ответ 1: arctan(5/12).','Определение угла прямой с плоскостью.','first'),S('Пункт 2: проекция','Какая точка является проекцией D на ABB₁?','DA⊥(ABB₁), значит проекция D — A, проекция DB₁ — AB₁. Диагональ AB₁=√(5²+12²)=13 см.','Перпендикулярные рёбра и теорема Пифагора.','face'),S('Пункт 2: угол','Как найти угол DB₁A?','В прямоугольном DAB₁ тангенс искомого угла равен DA/AB₁=7/13. Ответ 2: arctan(7/13).','Тангенс в прямоугольном треугольнике.','second')], 'Для каждого пункта построй ортогональную проекцию прямой на данную грань.')
p,e=box(7,5,12)
L(17,6,'Углы с основаниями','В прямоугольном параллелепипеде ABCDA₁B₁C₁D₁ AB=5 см, AD=7 см, AA₁=12 см. Найдите угол: 1) между DC₁ и плоскостью A₁B₁C₁; 2) между B₁D и плоскостью ABC.','Реши оба пункта.',M(p,e,{'first':V('Проекция DC₁ на верхнее основание — D₁C₁',polygon=['D','D1','C1']),'base':V('Диагональ основания DB',segments=[['D','B']]),'second':V('Проекция DB₁ на основание — DB',polygon=['D','B','B1'])}),[
 S('Пункт 1','Какой угол образуется с верхним основанием?','Проекция D на верхнее основание — D₁, поэтому искомый угол ∠DC₁D₁. tan∠DC₁D₁=DD₁/D₁C₁=12/5. Ответ 1: arctan(12/5).','Определение угла прямой с плоскостью.','first'),S('Диагональ основания','Какова проекция DB₁ на нижнее основание?','Это DB, так как B₁ проектируется в B. DB=√(5²+7²)=√74 см.','Теорема Пифагора в основании.','base'),S('Пункт 2','Каков угол B₁DB?','tan∠B₁DB=BB₁/DB=12/√74. Ответ 2: arctan(12/√74).','Тангенс в прямоугольном треугольнике.','second')], 'Угол с плоскостью измеряется до проекции прямой.')
