L(17,10,'Сечение куба по полной поверхности','Площадь поверхности куба равна 216 см². Найдите площадь диагонального сечения.','Найди площадь сечения.',M(p,e,{'face':V('Квадратная грань',polygon=list('ABCD')),'section':V('Диагональное сечение ACC₁A₁',polygon=['A','C','C1','A1'])}),[
 S('Ребро','Как поверхность связана с a?','У куба шесть квадратных граней, поэтому 6a²=216. Отсюда a²=36 и a=6 см.','Площадь поверхности куба.','face'),S('Сечение','Каковы стороны прямоугольника?','Диагональное сечение имеет стороны a и a√2: боковое ребро и диагональ основания.','Строение диагонального сечения куба.','section'),S('Площадь','Чему равно их произведение?','S=a²√2=36√2 см².','Площадь прямоугольника.','section')], 'Сечение имеет площадь a²√2.')
