L(17,20,'Высота по двугранному углу','В прямом параллелепипеде ABCDA₁B₁C₁D₁ AD=8 см, ∠BAD=30°. Угол между плоскостями ABC и A₁CD равен 45°. Найдите высоту.','Найди высоту.',M(p,e,{'base':V('AH — перпендикуляр к прямой CD',polygon=list('ABCD'),segments=[['A','H'],['H','D']]),'angle':V('Линейный угол AHA₁',polygon=['A','H','A1'])},labels=['A','B','C','D','A1','H']),[
 S('Расстояние до CD','Как получить AH из AD?','CD∥AB, поэтому расстояние A до прямой CD равно AD sin∠BAD=8sin30°=4 см. Обозначим основание перпендикуляра H; оно может лежать на продолжении CD.','Расстояние между параллельными прямыми.','base'),S('Линейный угол','Почему ∠AHA₁=45°?','AH⊥CD, а AA₁⊥основанию. По теореме о трёх перпендикулярах A₁H⊥CD. Значит угол между AH и A₁H равен данному углу между плоскостями,45°.','Линейный угол и теорема о трёх перпендикулярах.','angle'),S('Высота','Каков катет AA₁?','В прямоугольном AA₁H имеем AA₁=AH tan45°=4 см.','Тангенс в прямоугольном треугольнике.','angle')], 'Нужна высота параллелограмма к стороне CD.',accepted=['4'])
