L(17,23,'Боковая поверхность по двум сечениям','Основание прямого параллелепипеда — ромб. Площади диагональных сечений равны S₁ и S₂. Найдите площадь боковой поверхности.','Выведи формулу через S₁,S₂.',M(p,e,{'sections':V('Диагональные сечения',segments=[['A','C'],['A1','C1'],['B','D'],['B1','D1']]),'triangle':V('Половины диагоналей ромба',segments=[['A','C'],['B','D'],['A','B']]),'side':V('Боковая грань',polygon=['A','B','B1','A1'])}),[
 S('Площади сечений','Как выразить их через диагонали p,q и высоту h?','Диагональные сечения — прямоугольники, поэтому S₁=ph, S₂=qh.','Свойства прямого параллелепипеда.','sections'),S('Сторона ромба','Как связать a с p,q?','Диагонали ромба перпендикулярны и делятся пополам, поэтому a²=(p/2)²+(q/2)². Следовательно 4a²=p²+q².','Пифагор в четверти ромба.','triangle'),S('Боковая площадь','Как исключить p,q,h?','Sбок=4ah=2√(p²h²+q²h²)=2√(S₁²+S₂²).','Периметр ромба, боковая поверхность и положительность длин.','side')], 'Используй прямоугольный треугольник из половин диагоналей ромба.')
p,e=rhombus(3,60,4)
L(17,24,'Высота по трём площадям','Основание прямого параллелепипеда — ромб площади S. Площади диагональных сечений равны S₁ и S₂. Найдите высоту.','Вырази высоту через S,S₁,S₂.',M(p,e,{'base':V('Ромб основания и его диагонали',polygon=list('ABCD'),segments=[['A','C'],['B','D']]),'sections':V('Высота общая для обоих сечений',segments=[['A','C'],['B','D'],['A','A1']])}),[
 S('Основание','Как записать площадь через диагонали p,q?','Поскольку диагонали ромба перпендикулярны, S=pq/2, то есть pq=2S.','Площадь ромба по диагоналям.','base'),S('Сечения','Что даёт произведение их площадей?','S₁=ph, S₂=qh. Поэтому S₁S₂=pq·h²=2S·h².','Площадь прямоугольных диагональных сечений.','sections'),S('Высота','Какой корень нужно взять?','h²=S₁S₂/(2S), откуда h=√[S₁S₂/(2S)]. Высота положительна.','Решение равенства относительно положительной длины.','sections')], 'Перемножь площади сечений, чтобы появилась площадь основания.')
