L(17,25,'Наклон сечения к основанию','В прямом параллелепипеде ABCDA₁B₁C₁D₁ BC=8 см, CD=4 см, ∠BCD=60°. Плоскость BDC₁ образует с основанием угол 30°. Найдите площадь боковой поверхности.','Найди боковую площадь.',M(p,e,{'base':V('Треугольник BCD прямоугольный при D',polygon=['B','C','D']),'angle':V('Линейный угол CDC₁ равен 30°',polygon=['C','D','C1']),'section':V('Сечение BDC₁',polygon=['B','D','C1'])}),[
 S('Треугольник основания','Почему CD перпендикулярен BD?','BD²=8²+4²−2·8·4 cos60°=48. Тогда BD²+CD²=48+16=64=BC², поэтому ∠BDC=90°. Расстояние C до BD равно CD=4 см.','Теорема косинусов и обратная теорема Пифагора.','base'),S('Высота','Как использовать угол плоскостей?','CD⊥BD и CC₁⊥основанию, поэтому C₁D⊥BD. Угол CDC₁=30° — линейный угол плоскостей. Значит h=CC₁=CD tan30°=4/√3 см.','Теорема о трёх перпендикулярах и тангенс.','angle'),S('Площадь','Каков периметр основания?','P=2(8+4)=24 см. Поэтому Sбок=Ph=24·4/√3=32√3 см².','Площадь боковой поверхности прямой призмы.','section')], 'Докажи, что треугольник BCD прямоугольный при D.')
