L(17,26,'Вершина равноудалена от основания','Основание наклонного параллелепипеда ABCDA₁B₁C₁D₁ — квадрат со стороной 8 см. Вершина A₁ равноудалена от всех вершин основания; боковое ребро равно 6 см. Найдите высоту.','Найди высоту.',M(p,e,{'equal':V('Равные расстояния от A₁ до четырёх вершин',segments=[['A1',k] for k in 'ABCD']),'projection':V('O — центр квадрата и проекция A₁',polygon=['A','O','A1']),'base':V('Диагонали квадрата',segments=[['A','C'],['B','D']])}),[
 S('Проекция вершины','Почему она совпадает с центром квадрата?','Пусть H — проекция A₁ на основание. По Пифагору A₁A²=A₁H²+HA² и аналогично для B,C,D. Равенство расстояний от A₁ даёт HA=HB=HC=HD, поэтому H — центр описанной окружности квадрата O.','Пифагор и единственность центра окружности через вершины квадрата.','equal'),S('Расстояние AO','Чему равна половина диагонали?','Диагональ квадрата 8√2, поэтому AO=4√2 см. Боковое ребро AA₁=6 см.','Диагональ квадрата и её середина.','base'),S('Высота','Как найти катет A₁O?','h²=AA₁²−AO²=36−32=4. Значит h=2 см.','Пифагор в прямоугольном AA₁O.','projection')], 'Проекция равноудалённой вершины равноудалена от всех четырёх вершин квадрата.',accepted=['2'])
