L(17,27,'Площадь грани наклонного параллелепипеда','Основание наклонного параллелепипеда ABCDA₁B₁C₁D₁ — квадрат; все его рёбра равны 8 см. Противоположные грани AA₁B₁B и CC₁D₁D перпендикулярны основанию. Найдите площадь грани AA₁D₁D.','Найди площадь указанной грани.',M(p,e,{'perp':V('Грань ABB₁A₁ перпендикулярна основанию',polygon=['A','B','B1','A1']),'base':V('AD перпендикулярен AB',segments=[['A','B'],['A','D']]),'target':V('Грань ADD₁A₁ — квадрат',polygon=['A','D','D1','A1'])}),[
 S('Перпендикуляр в основании','Как расположено AD к следу боковой грани?','В квадрате AD⊥AB. Плоскости ABB₁A₁ и основания перпендикулярны, а их линия пересечения — AB.','Свойства квадрата и условие задачи.','base'),S('Перпендикуляр к плоскости','Что следует для AD?','Прямая AD лежит в основании и перпендикулярна линии пересечения перпендикулярных плоскостей. Значит AD⊥(ABB₁A₁), в частности AD⊥AA₁.','Свойство перпендикулярных плоскостей.','perp'),S('Площадь','Какой стала искомая грань?','Параллелограмм ADD₁A₁ имеет прямой угол и соседние стороны AD=AA₁=8. Это квадрат, его площадь 8·8=64 см².','Признак прямоугольника и площадь квадрата.','target')], 'Докажи, что AD перпендикулярно всей плоскости ABB₁A₁.',accepted=['64'])
