L(17,28,'Биссектриса из вершины основания','В равнобедренном треугольнике ABC AC=BC, AB=2√2 см, ∠BAC=30°. Найдите биссектрису AD.','Найди длину AD.',M(p,e,{'angles':V('AD делит угол A пополам',segments=[['A','D'],['A','B'],['A','C']]),'triangle':V('Треугольник ABD',polygon=['A','B','D'])},planar=True),[
 S('Углы','Каковы углы треугольника ABD?','Основание равнобедренного треугольника — AB, поэтому ∠ABC=∠BAC=30°. Биссектриса даёт ∠BAD=15°, а ∠ABD=30°.','Углы при основании и определение биссектрисы.','angles'),S('Третий угол','Чему равен ∠ADB?','∠ADB=180°−15°−30°=135°.','Сумма углов треугольника.','triangle'),S('Длина биссектрисы','Как применить теорему синусов?','AD/sin30°=AB/sin135°, поэтому AD=2√2·(1/2)/(√2/2)=2 см.','Теорема синусов.','triangle')], 'Работай с треугольником ABD, где известны основание и два угла.',accepted=['2'])
